from collections.abc import Callable
from dataclasses import replace
from typing import cast

from .nodes import (
    AliasNode,
    AndNode,
    BinaryOperationNode,
    DeleteQueryNode,
    IdentifierNode,
    InsertQueryNode,
    IsNullNode,
    JoinNode,
    NotNode,
    OperationNode,
    OrderByItemNode,
    OrNode,
    ReferenceNode,
    SelectAllNode,
    SelectQueryNode,
    SetOperationNode,
    TableNode,
    UpdateQueryNode,
    ValueListNode,
    ValueNode,
